T['en:422']=[{"t": "title", "x": "النفي مع This / That / These / Those"}, {"t": "sub", "x": "Negative Sentences with Demonstratives"}, {"t": "table", "head": ["التركيب", "مثال"], "rows": [["This / That + is not + a / an + اسم", "This is not a book. / That is not an apple."], ["These / Those + are not + اسم جمع", "These are not cats. / Those are not girls."]], "ltr": 1}, {"t": "p", "x": "الاختصار: is not = isn't ، are not = aren't."}, {"t": "quiz", "q": "اختر الصحيح:", "o": ["These is not cats.", "These are not cats.", "These not are cats."], "a": 1}, {"t": "quiz", "q": "اختر الصحيح:", "o": ["That is not a bag.", "That not is a bag.", "That are not a bag."], "a": 0}, {"t": "quiz", "q": "اختصار are not:", "o": ["aren't", "isn't", "don't"], "a": 0}];
T['en:427']=[{"t": "title", "x": "السؤال مع This / That / These / Those"}, {"t": "sub", "x": "Questions and Short Answers"}, {"t": "p", "x": "نبدأ السؤال بـ Is مع المفرد، وبـ Are مع الجمع."}, {"t": "table", "head": ["السؤال", "الإجابة بنعم", "الإجابة بلا"], "rows": [["Is this a girl?", "Yes, this is a girl.", "No, this is not a girl."], ["Is that a book?", "Yes, that is a book.", "No, that is not a book."], ["Are these books?", "Yes, these are books.", "No, these are not books."], ["Are those cats?", "Yes, those are cats.", "No, those are not cats."]], "ltr": 1}, {"t": "quiz", "q": "اختر السؤال الصحيح:", "o": ["Are this a girl?", "Is this a girl?", "This is a girl?"], "a": 1}, {"t": "quiz", "q": "اختر السؤال الصحيح:", "o": ["Is these books?", "These are books?", "Are these books?"], "a": 2}, {"t": "quiz", "q": "مع الجمع نبدأ السؤال بـ:", "o": ["Are", "Is", "Do"], "a": 0}];
T['en:435']=[{"t": "title", "x": "ظروف التكرار"}, {"t": "sub", "x": "Adverbs of Frequency"}, {"t": "p", "x": "تخبرنا ظروف التكرار كم مرة يحدث الفعل."}, {"t": "table", "head": ["Adverb", "النسبة", "المعنى"], "rows": [["always", "100%", "دائمًا"], ["usually", "90%", "عادةً"], ["often", "70%", "غالبًا"], ["sometimes", "50%", "أحيانًا"], ["rarely", "10%", "نادرًا"], ["never", "0%", "أبدًا"]], "ltr": 1}, {"t": "sec", "n": 1, "x": "موضعها في الجملة"}, {"t": "ul", "x": ["قبل الفعل العادي: {{I always do my homework.}} ، {{She usually goes to school.}}", "بعد فعل الكينونة be: {{I am never late.}} ، {{She is usually late.}}"]}, {"t": "table", "head": ["خطأ", "صحيح"], "rows": [["He always play football.", "He always plays football."], ["I never am late.", "I am never late."]], "ltr": 1}, {"t": "sec", "n": 2, "x": "سؤال وجواب"}, {"t": "ul", "x": ["{{How often do you exercise?}} – {{I often exercise in the evening.}}", "{{Do you always get up early?}} – {{No, I usually get up at 6:30.}}"]}, {"t": "quiz", "q": "ما معنى never؟", "o": ["دائمًا", "أبدًا", "أحيانًا"], "a": 1}, {"t": "quiz", "q": "اختر الصحيح:", "o": ["I never am late.", "I am never late.", "I am late never."], "a": 1}, {"t": "quiz", "q": "الأقل تكرارًا بين الكلمات:", "o": ["often", "usually", "rarely"], "a": 2}];
T['en:436']=[{"t": "title", "x": "Look / Watch / See"}, {"t": "sub", "x": "Look – Watch – See"}, {"t": "table", "head": ["Verb", "المعنى", "أمثلة"], "rows": [["look (at)", "ينظر بقصد إلى شيء", "look at the board ، look for my keys (يبحث عن)"], ["watch", "يشاهد شيئًا يتحرك أو يتغيّر لفترة", "watch TV ، watch a movie ، watch the sunset"], ["see", "يرى بالعين دون قصد، أو يفهم", "I see a bird. ، I see what you mean."]], "ltr": 1}, {"t": "ul", "x": ["{{Look! There is Ali.}} انظر! هناك علي.", "{{I'm watching a documentary now.}} أشاهد فيلمًا وثائقيًا الآن.", "{{Did you see the news?}} هل رأيت الأخبار؟", "{{I didn't see you there.}} لم أرك هناك."]}, {"t": "note", "x": "نقول look at مع حرف الجر at، ولا نقول look فقط عند ذكر المنظور إليه."}, {"t": "quiz", "q": "أكمل: ___ TV.", "o": ["Watch", "See", "Look"], "a": 0}, {"t": "quiz", "q": "أكمل: ___ at the board.", "o": ["Look", "Watch", "See"], "a": 0}, {"t": "quiz", "q": "في I see what you mean تعني see:", "o": ["أفهم", "أشاهد", "أنظر"], "a": 0}];
T['en:437']=[{"t": "title", "x": "حروف الجر in / on / at"}, {"t": "sub", "x": "Prepositions of Place and Time: in – on – at"}, {"t": "table", "head": ["الحرف", "المكان", "الزمان"], "rows": [["in", "in the room ، in the bag ، in Cairo", "in summer ، in 2025 ، in the morning"], ["on", "on the table ، on the wall", "on Monday ، on 5th May ، on my birthday"], ["at", "at the door ، at the bus stop ، at home", "at 7 o'clock ، at noon ، at night"]], "ltr": 1}, {"t": "ul", "x": ["{{I live in Cairo.}} أسكن في القاهرة.", "{{The book is on the table.}} الكتاب على الطاولة.", "{{Let's meet at 5 p.m.}} لنلتقِ الساعة الخامسة مساءً.", "{{My birthday is on 10th October.}} عيد ميلادي في العاشر من أكتوبر."]}, {"t": "note", "x": "in للأماكن والأزمنة الواسعة (شهر، سنة، فصل)، وon للأيام والتواريخ والأسطح، وat للنقاط المحددة والساعات."}, {"t": "quiz", "q": "أكمل: I get up ___ 7 o'clock.", "o": ["in", "at", "on"], "a": 1}, {"t": "quiz", "q": "أكمل: The party is ___ Friday.", "o": ["in", "at", "on"], "a": 2}, {"t": "quiz", "q": "أكمل: We go to the beach ___ summer.", "o": ["on", "at", "in"], "a": 2}];
T['en:438']=[{"t": "title", "x": "الصفة والظرف"}, {"t": "sub", "x": "Adjective or Adverb?"}, {"t": "table", "head": ["", "الوظيفة", "يجيب عن"], "rows": [["Adjective (صفة)", "يصف الاسم", "أي نوع؟ ما صفته؟"], ["Adverb (ظرف)", "يصف الفعل أو الصفة", "كيف؟ متى؟ أين؟ كم مرة؟"]], "ltr": 1}, {"t": "ul", "x": ["{{She is a beautiful girl.}} (صفة تصف girl)", "{{She sings beautifully.}} (ظرف يصف sings)", "{{He is a clever boy.}} (صفة)", "{{He speaks English fluently.}} (ظرف)"]}, {"t": "p", "x": "نكوّن الظرف غالبًا بإضافة -ly إلى الصفة: quick → quickly ، careful → carefully ، beautiful → beautifully."}, {"t": "note", "x": "بعض الكلمات تنتهي بـ -ly وهي صفات لا ظروف، مثل friendly و lovely. وبعض الظروف تشبه الصفة مثل fast و hard، والظرف من good هو well."}, {"t": "quiz", "q": "اختر: She drives ___.", "o": ["carefully", "careful", "care"], "a": 0}, {"t": "quiz", "q": "اختر: He is a ___ boy.", "o": ["cleverly", "clever", "cleverness"], "a": 1}, {"t": "quiz", "q": "في She sings beautifully كلمة beautifully:", "o": ["ظرف", "صفة", "اسم"], "a": 0}];
T['en:439']=[{"t": "title", "x": "Some و Any"}, {"t": "sub", "x": "Some – Any"}, {"t": "table", "head": ["الكلمة", "الاستخدام", "مثال"], "rows": [["some", "في الجملة المثبتة، وفي العرض والطلب", "I have some books. ، Can I have some tea?"], ["any", "في النفي والسؤال", "I don't have any money. ، Do you have any questions?"]], "ltr": 1}, {"t": "ul", "x": ["{{She wants some water.}} تريد بعض الماء.", "{{There are some apples in the fridge.}} توجد بعض التفاح في الثلاجة.", "{{Is there any milk in the fridge?}} هل يوجد حليب في الثلاجة؟", "{{If you need any help, call me.}} إن احتجت أي مساعدة فاتصل بي."]}, {"t": "quiz", "q": "أكمل: I don't have ___ money.", "o": ["some", "a", "any"], "a": 2}, {"t": "quiz", "q": "أكمل: She wants ___ water.", "o": ["some", "any", "an"], "a": 0}, {"t": "quiz", "q": "أكمل: Do you have ___ questions?", "o": ["some", "an", "any"], "a": 2}];
T['en:440']=[{"t": "title", "x": "Too و Enough"}, {"t": "sub", "x": "Too – Enough"}, {"t": "table", "head": ["الكلمة", "المعنى", "التركيب", "مثال"], "rows": [["too", "أكثر من اللازم (غالبًا سلبي)", "too + صفة / ظرف", "The coffee is too hot."], ["enough", "كافٍ", "صفة / ظرف + enough ، وenough + اسم", "The coffee is hot enough. ، I have enough money."]], "ltr": 1}, {"t": "ul", "x": ["{{This bag is too heavy.}} هذه الحقيبة ثقيلة جدًّا.", "{{He is too tired to go out.}} هو متعب جدًّا فلا يخرج.", "{{He is strong enough to lift it.}} هو قوي بما يكفي ليرفعها.", "{{You don't talk enough.}} لا تتحدث بما يكفي."]}, {"t": "note", "x": "too قبل الصفة، وenough بعد الصفة. أما مع الاسم فتأتي enough قبله: enough food."}, {"t": "quiz", "q": "اختر الصحيح:", "o": ["hot too", "too hot", "enough hot"], "a": 1}, {"t": "quiz", "q": "اختر الصحيح:", "o": ["enough strong", "strong enough", "too strong enough"], "a": 1}, {"t": "quiz", "q": "اختر الصحيح:", "o": ["enough money", "money enough", "too money"], "a": 0}];
T['en:441']=[{"t": "title", "x": "A little و A few"}, {"t": "sub", "x": "A little – A few"}, {"t": "table", "head": ["الكلمة", "مع", "مثال"], "rows": [["a little", "اسم غير معدود", "I have a little time. ، There is a little milk in the fridge."], ["a few", "اسم جمع معدود", "I have a few friends. ، She has a few questions."]], "ltr": 1}, {"t": "note", "x": "بدون a تصبح little و few بمعنى «قليل جدًا تكاد تنعدم»: I have little time. ، I have few friends."}, {"t": "quiz", "q": "أكمل: There is ___ milk.", "o": ["a few", "many", "a little"], "a": 2}, {"t": "quiz", "q": "أكمل: I have ___ friends.", "o": ["a few", "a little", "much"], "a": 0}, {"t": "quiz", "q": "little بدون a تعني:", "o": ["بعض", "قليل جدًا", "كثير"], "a": 1}];
T['en:442']=[{"t": "title", "x": "عبارات يومية (1)"}, {"t": "sub", "x": "Everyday Expressions – Part 1"}, {"t": "table", "head": ["English", "العربية"], "rows": [["Good morning!", "صباح الخير!"], ["How are you?", "كيف حالك؟"], ["I'm fine, thank you.", "بخير، شكرًا."], ["What's your name?", "ما اسمك؟"], ["Nice to meet you.", "سعدت بلقائك."], ["Where are you from?", "من أين أنت؟"], ["What do you do?", "ماذا تعمل؟"], ["I don't understand.", "لا أفهم."], ["Can you help me?", "هل تستطيع مساعدتي؟"], ["Thank you so much!", "شكرًا جزيلًا!"]], "ltr": 1}, {"t": "words", "x": ["Good morning", "How are you", "I'm fine", "What's your name", "Nice to meet you", "Where are you from", "What do you do", "I don't understand", "Can you help me", "Thank you so much"], "l": "en"}, {"t": "quiz", "q": "ما معنى What do you do؟", "o": ["ماذا تعمل؟", "ماذا تفعل الآن؟", "ما اسمك؟"], "a": 0}, {"t": "quiz", "q": "للسؤال عن البلد نقول:", "o": ["How are you?", "Where are you from?", "What's your name?"], "a": 1}, {"t": "quiz", "q": "ما معنى I don't understand؟", "o": ["لا أعرف", "لا أفهم", "لا أريد"], "a": 1}];
